def solve(nums):
    # Handle trivial cases
    if len(nums) <= 1:
        return list(nums)
    a = list(nums)
    n = len(a)
    # Find first decreasing point from the right
    i = n - 1
    while i > 0 and a[i-1] >= a[i]:
        i -= 1
    if i == 0:
        # Last permutation: return lowest (sorted) order
        return sorted(a)
    pivot = i - 1
    # Find rightmost element greater than pivot
    j = n - 1
    while a[j] <= a[pivot]:
        j -= 1
    a[pivot], a[j] = a[j], a[pivot]
    # Reverse the suffix
    a[i:] = reversed(a[i:])
    return a

