def solve(tokens):
    """Evaluate an RPN expression with operators +, -, *, /.
    Division truncates toward zero.
    Returns 0 for empty input.
    """
    if not tokens:
        return 0
    stack = []
    def trunc_div(a, b):
        if b == 0:
            raise ZeroDivisionError('division by zero')
        q = abs(a) // abs(b)
        return q if a * b >= 0 else -q
    ops = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': trunc_div,
    }
    for token in tokens:
        if token in ops:
            # Assuming valid RPN: enough operands
            b = stack.pop()
            a = stack.pop()
            stack.append(ops[token](a, b))
        else:
            # token is an integer literal
            stack.append(int(token))
    # After processing, the result should be the sole element
    return stack[-1] if stack else 0

