def solve(nums):
    """Return the next lexicographic permutation of nums as a new list.
    Handles empty list by returning [].
    If nums is the highest permutation, returns sorted (ascending) list.
    """
    if not nums:
        return []
    a = nums[:]  # copy
    n = len(a)
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i == -1:
        return sorted(a)
    j = n - 1
    while a[j] <= a[i]:
        j -= 1
    a[i], a[j] = a[j], a[i]
    a[i+1:] = reversed(a[i+1:])
    return a

