        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if (i,j) in visited:
                continue
            visited.add((i,j))
            # explore 4 dirs
            for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
