    """Count the number of islands in a possibly ragged binary grid.
    An island is a group of orthogonally connected cells with value 1.
    Handles empty grid and rows of varying lengths.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def bfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            # explore 4 directions
            for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < rows and 0 <= nj < len(grid[ni]) and grid[ni][nj] == 1:
                    if (ni, nj) not in visited:
                        stack.append((ni, nj))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                bfs(i, j)
                count += 1
    return count

