def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search for O(n log n) time.
    """
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # Find insertion point: leftmost tail >= x (since we need strictly increasing)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

