def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Supports operators '+', '-', '*', '/' with integer division truncating toward zero.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                # Truncate toward zero
                # Use int(a / b) which truncates toward zero in Python 3
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

